1170	@@ -0,0 +1,43 @@
1171	+import type { MatchReport as FlowReport } from "@pirate-sea-race/simulation/match";
1172	+
1173	+/** The reports for the flow's next step, and those dropped for naming a player the flow does not know. */
1174	+export interface KnownFlowReports {
1175	+  readonly reports: readonly FlowReport[];
1176	+  readonly dropped: readonly FlowReport[];
1177	+}
1178	+
1179	+/**
1180	+ * The room's reports as the match module may take them (`stepMatch` throws on an unknown player id): a join makes its
1181	+ * player known for the reports after it; a duel's end naming a fighter, a claim's end naming a winner, or an
1182	+ * accomplishment naming a player the flow does not know is dropped. A leave or a start of an unknown player is kept
1183	+ * (the match module ignores the one and refuses the other), and so is a fault. The order of the kept reports is theirs.
1184	+ */
1185	+export function knownFlowReports(players: readonly { readonly id: string }[], reports: readonly FlowReport[]): KnownFlowReports {
1186	+  const known = new Set(players.map((player) => player.id));
1187	+  const kept: FlowReport[] = [];
1188	+  const dropped: FlowReport[] = [];
1189	+  for (const report of reports) {
1190	+    if (report.kind === "join") known.add(report.playerId);
1191	+    else if (!namesKnownPlayers(report, known)) {
1192	+      dropped.push(report);
1193	+      continue;
1194	+    }
1195	+    kept.push(report);
1196	+  }
1197	+  return { reports: kept, dropped };
1198	+}
1199	+
1200	+function namesKnownPlayers(report: FlowReport, known: ReadonlySet<string>): boolean {
1201	+  switch (report.kind) {
1202	+    case "duel-ended":
1203	+      return report.playerIds.every((id) => known.has(id));
1204	+    case "match-ended":
1205	+      return report.winner === null || known.has(report.winner);
1206	+    case "leave":
1207	+    case "start":
1208	+    case "fault":
1209	+      return true;
1210	+    default:
1211	+      return known.has(report.playerId);
1212	+  }
1213	+}
