1	import { WORLD_STEPS_PER_SECOND } from "@pirate-sea-race/content";
2	import { parseRevealMessage, startRefusedMessageSchema, type RevealMessage, type StartRefusedMessage } from "@pirate-sea-race/protocol";
3	import { compassToward, secondsUntil, typeName, type HudLine } from "./hud.js";
4	
5	/**
6	 * The match flow on the page (§2, §5): the lobby, the ready countdown, the timer, the reveals' banners, the route to
7	 * the final island, the claim and the results screen. The functions here are pure (tests call them without a DOM);
8	 * `renderFlow` writes them into the page.
9	 */
10	
11	/** A seat as the page names it: "Player 2", with "you" and "host" where they apply. */
12	export function seatLabel(seat: number, self: number, host: number): string {
13	  const tags = [seat === self ? "you" : "", seat === host ? "host" : ""].filter((tag) => tag !== "");
14	  return `Player ${seat}${tags.length > 0 ? ` (${tags.join(", ")})` : ""}`;
15	}
16	
17	/** Minutes and seconds of world ticks, rounded up to the second: 42 000 ticks is "35:00". */
18	export function clockText(ticks: number): string {
19	  const seconds = Math.max(0, Math.ceil(ticks / WORLD_STEPS_PER_SECOND));
20	  return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}`;
21	}
22	
23	/** What the lobby shows (§2): the players by seat, whether this player may start, and why not. */
24	export interface LobbyModel {
25	  readonly players: readonly { readonly seat: number; readonly label: string }[];
26	  /** The Start button is shown to the host only, and enabled with enough players. */
27	  readonly showStart: boolean;
28	  readonly canStart: boolean;
29	  readonly hint: string;
30	}
31	
32	export interface LobbyState {
33	  readonly phase: string;
34	  readonly seats: readonly number[];
35	  readonly hostSeat: number;
36	  readonly seat: number;
37	  readonly minPlayers: number;
38	  readonly readyEndsAt: number;
39	  readonly worldTick: number;
40	}
41	
42	export function lobbyModel(state: LobbyState): LobbyModel {
43	  const seats = [...state.seats].sort((a, b) => a - b);
44	  const players = seats.map((seat) => ({ seat, label: seatLabel(seat, state.seat, state.hostSeat) }));
45	  const host = state.seat !== 0 && state.seat === state.hostSeat;
46	  const enough = seats.length >= state.minPlayers;
47	  if (state.phase === "ready") {
48	    const seconds = secondsUntil(state.readyEndsAt, state.worldTick);
49	    return { players, showStart: false, canStart: false, hint: `Setting sail in ${seconds} s: the arena loads meanwhile` };
50	  }
51	  let hint: string;
52	  if (!enough) hint = `Waiting for players: ${state.minPlayers} or more start a match. Share the code.`;
53	  else if (host) hint = "Everyone aboard? Start the match.";
54	  else hint = "Waiting for the host to start the match.";
55	  return { players, showStart: host, canStart: host && enough && state.phase === "lobby", hint };
56	}
57	
58	/** Why the host's start was refused, as the lobby says it. */
59	export function startRefusalText(reason: StartRefusedMessage["reason"]): string {
60	  switch (reason) {
61	    case "too-few":
62	      return "A private match needs at least two players to start.";
63	    case "not-host":
64	      return "Only the host can start the match.";
65	    default:
66	      return "This match starts when its seats fill.";
67	  }
68	}
69	
70	/** The lobby's line for the server's refusal of a start, or undefined for a message that is not one. */
71	export function startRefusalLine(message: unknown): string | undefined {
72	  const refusal = startRefusedMessageSchema.safeParse(message);
73	  return refusal.success ? startRefusalText(refusal.data.reason) : undefined;
74	}
75	
76	/** The server's refusal of a start, shown in the lobby; anything that is not one is ignored. */
77	export function showStartRefusal(message: unknown, show: (line: string) => void): void {
78	  const line = startRefusalLine(message);
79	  if (line !== undefined) show(line);
80	}
81	
82	/** A reveal from the server, shown as its banner; anything that is not one is ignored. */
83	export function showReveal(message: unknown, show: (banner: Banner) => void): void {
84	  const reveal = parseRevealMessage(message);
85	  if (reveal !== undefined) show(revealBanner(reveal));
86	}
87	
88	/** The phase as the HUD names it. */
89	export function phaseText(phase: string): string {
90	  switch (phase) {
91	    case "lobby":
92	      return "Lobby";
93	    case "ready":
94	      return "Ready check";
95	    case "departure":
96	      return "Departure (protected)";
97	    case "exploration":
98	      return "Exploration";
99	    case "ended":
100	      return "Match over";
101	    default:
102	      return "";
103	  }
104	}
105	
106	/**
107	 * The match timer (§2): the full duration in the lobby and the ready check, counting down from control start, frozen
108	 * at the end. `urgent` in the last minute.
109	 */
110	export function timerLine(state: { readonly phase: string; readonly remainingTicks: number }): HudLine {
111	  const text = clockText(state.remainingTicks);
112	  if (state.phase === "lobby" || state.phase === "ready") return { text, state: "waiting" };
113	  if (state.phase === "ended") return { text, state: "ended" };
114	  return { text, state: state.remainingTicks <= 60 * WORLD_STEPS_PER_SECOND ? "urgent" : "running" };
115	}
116	
117	/** A reveal as a banner for everyone who receives it (§2, §5): a headline, a detail line and a tone for styling. */
118	export interface Banner {
119	  readonly kind: RevealMessage["kind"];
120	  readonly title: string;
121	  readonly detail: string;
122	  readonly tone: "treasure" | "warning" | "info";
123	}
124	
125	export function revealBanner(reveal: RevealMessage): Banner {
126	  switch (reveal.kind) {
127	    case "final-sector":
128	      return { kind: reveal.kind, title: "A full set of rubbings exists!", detail: `The treasure lies in ${reveal.name}. Every ship is heading there.`, tone: "treasure" };
129	    case "final-route":
130	      return {
131	        kind: reveal.kind,
132	        title: reveal.restored ? "Your set is whole again" : "You hold every rubbing!",
133	        detail: "Your compass points to the final island. Stop inside the treasure circle and hold E to claim it.",
134	        tone: "treasure",
135	      };
136	    case "final-route-inactive":
137	      return { kind: reveal.kind, title: "You lost a rubbing", detail: "Your route to the treasure is inactive until your set is whole again.", tone: "warning" };
138	    case "sector-reveal": {
139	      const sources = reveal.sources.map((sector) => sector.name);
140	      const caches = reveal.caches.map((sector) => sector.name);
141	      const parts = [sources.length > 0 ? `unclaimed rubbings in ${sources.join(", ")}` : "no unclaimed rubbing left", caches.length > 0 ? `recovery caches in ${caches.join(", ")}` : ""];
142	      return { kind: reveal.kind, title: "Minute 20: the charts are out", detail: `${capitalise(parts.filter((part) => part !== "").join("; "))}.`, tone: "info" };
143	    }
144	    case "carrier-report": {
145	      const carriers = reveal.carriers.map((carrier) => `${typeName(carrier.type)} in ${carrier.name}`);
146	      return { kind: reveal.kind, title: "Carriers sighted", detail: carriers.length > 0 ? `${carriers.join(", ")}.` : "No rubbing is being carried.", tone: "info" };
147	    }
148	  }
149	}
150	
151	function capitalise(text: string): string {
152	  return text.charAt(0).toUpperCase() + text.slice(1);
153	}
154	
155	/** This player's route and claim, from their private status (§5). */
156	export interface ClaimStatus {
157	  readonly fullSet: boolean;
158	  readonly routeKnown: boolean;
159	  readonly routeActive: boolean;
160	  readonly routeX: number;
161	  readonly routeY: number;
162	  readonly claim: string;
163	  readonly claimHeld: number;
164	  readonly claimTotal: number;
165	  readonly claimInterrupt: string;
166	  readonly claimInterruptAt: number;
167	}
168	
169	/** The compass to the final island: the direction and distance in tiles, and the bearing in radians for the arrow. */
170	export interface RouteLine extends HudLine {
171	  /** Radians from east, clockwise (y grows south), or undefined without an active route. */
172	  readonly bearing?: number;
173	  readonly distanceTiles?: number;
174	}
175	
176	export function routeLine(claim: ClaimStatus | undefined, own: { x: number; y: number } | undefined, subUnitsPerTile: number): RouteLine {
177	  if (claim === undefined || !claim.routeKnown) return { text: "", state: "none" };
178	  if (!claim.routeActive) return { text: "Route inactive: win back the rubbing you lost", state: "inactive" };
179	  if (own === undefined) return { text: "Treasure route active", state: "active" };
180	  const target = { x: claim.routeX, y: claim.routeY };
181	  const distanceTiles = Math.round(Math.hypot(target.x - own.x, target.y - own.y) / subUnitsPerTile);
182	  const bearing = Math.atan2(target.y - own.y, target.x - own.x);
183	  const text = distanceTiles === 0 ? "Treasure: right here" : `Treasure: ${distanceTiles} tiles ${compassToward(own, target)}`;
184	  return { text, state: "active", bearing, distanceTiles };
185	}
186	
187	const INTERRUPTS: Readonly<Record<string, string>> = {
188	  duel: "a rival grappled you",
189	  disconnected: "you disconnected",
190	  ineligible: "you no longer hold every rubbing",
191	  moved: "you moved",
192	  released: "you let go of E",
193	  deadline: "time ran out",
194	};
195	
196	/** How recent a reset must be (in world ticks) for the claim line to still say why. */
197	const INTERRUPT_SHOWN_TICKS = 5 * WORLD_STEPS_PER_SECOND;
198	
199	/**
200	 * The claim (§5): what to do, the channel's seconds left, or why it reset; `risk` is the explicit warning while the
201	 * channel runs or can start. `progress` is 0 to 1.
202	 */
203	export function claimLines(
204	  claim: ClaimStatus | undefined,
205	  context: { readonly inCircle: boolean; readonly speed: number; readonly worldTick: number; readonly phase: string; readonly rivalClaiming?: boolean },
206	): { readonly claim: HudLine; readonly risk: HudLine; readonly progress: number } {
207	  const none = { claim: { text: "", state: "none" }, risk: { text: "", state: "none" }, progress: 0 };
208	  if (claim === undefined || context.phase === "ended") return none;
209	  // §5: a claim in sight warns everyone who sees it; interrupting it takes a grapple.
210	  if (context.rivalClaiming === true && claim.claim !== "channel" && claim.claim !== "waiting") {
211	    return { claim: { text: "A rival is claiming the treasure! Grapple them before the channel completes", state: "rival" }, risk: none.risk, progress: 0 };
212	  }
213	  const risk = { text: "Any rival in range can interrupt you with a grapple", state: "risk" };
214	  if (claim.claim === "channel") {
215	    const seconds = Math.max(0, Math.ceil((claim.claimTotal - claim.claimHeld) / WORLD_STEPS_PER_SECOND));
216	    return {
217	      claim: { text: `Claiming the treasure: keep holding E, ${seconds} s left`, state: "channel", seconds },
218	      risk,
219	      progress: claim.claimTotal === 0 ? 0 : Math.min(1, claim.claimHeld / claim.claimTotal),
220	    };
221	  }
222	  if (claim.claim === "waiting") return { claim: { text: "Another claim is under way: interrupt it or wait", state: "waiting" }, risk, progress: 0 };
223	  const interrupted = claim.claimInterrupt !== "" && context.worldTick - claim.claimInterruptAt <= INTERRUPT_SHOWN_TICKS;
224	  if (interrupted) {
225	    return { claim: { text: `Claim interrupted: ${INTERRUPTS[claim.claimInterrupt] ?? claim.claimInterrupt}. Progress lost.`, state: `interrupted:${claim.claimInterrupt}` }, risk: none.risk, progress: 0 };
226	  }
227	  if (!claim.routeKnown || !claim.routeActive || !claim.fullSet) return none;
228	  if (!context.inCircle) return { claim: { text: "Sail into the treasure circle to claim", state: "route" }, risk: none.risk, progress: 0 };
229	  if (context.speed !== 0) return { claim: { text: "Stop inside the circle, then hold E for ten seconds", state: "slow" }, risk, progress: 0 };
230	  return { claim: { text: "Hold E to claim the treasure (ten seconds)", state: "ready" }, risk, progress: 0 };
231	}
232	
233	/** One row of the results screen. */
234	export interface ResultRow {
235	  readonly seat: number;
236	  readonly label: string;
237	  readonly winner: boolean;
238	  readonly left: boolean;
239	  readonly cells: readonly number[];
240	}
241	
242	export const RESULT_COLUMNS = ["Rubbings", "Thefts", "Lost", "Duels won", "Duels lost", "Duels drawn", "Gold", "Caches", "Islands"] as const;
243	
244	export interface ResultsState {
245	  readonly endReason: string;
246	  readonly winnerSeat: number;
247	  readonly seat: number;
248	  readonly hostSeat: number;
249	  readonly lines: readonly {
250	    readonly seat: number;
251	    readonly winner: boolean;
252	    readonly left: boolean;
253	    readonly collected: number;
254	    readonly thefts: number;
255	    readonly lost: number;
256	    readonly duelsWon: number;
257	    readonly duelsLost: number;
258	    readonly duelsDrawn: number;
259	    readonly gold: number;
260	    readonly cachesClaimed: number;
261	    readonly islandsVisited: number;
262	  }[];
263	}
264	
265	/** The results screen (§2): the headline (the winner, or no winner and why) and each player's accomplishments. */
266	export function resultsModel(state: ResultsState): { readonly headline: string; readonly detail: string; readonly rows: readonly ResultRow[] } | undefined {
267	  if (state.endReason === "") return undefined;
268	  let headline: string;
269	  let detail: string;
270	  switch (state.endReason) {
271	    case "claim":
272	      headline = state.winnerSeat === state.seat ? "You claimed the treasure!" : `Player ${state.winnerSeat} claimed the treasure`;
273	      detail = state.winnerSeat === state.seat ? "The One Piece is yours. Victory." : "The race is over.";
274	      break;
275	    case "deadline":
276	      headline = "No winner (time ran out)";
277	      detail = "Nobody claimed the treasure before the deadline.";
278	      break;
279	    case "abandoned":
280	      headline = "No winner (everyone left)";
281	      detail = "The match was abandoned.";
282	      break;
283	    default:
284	      headline = "No winner (match aborted)";
285	      detail = "A server fault stopped the match. No result counts against anyone.";
286	  }
287	  const rows = state.lines.map((line) => ({
288	    seat: line.seat,
289	    label: seatLabel(line.seat, state.seat, 0) + (line.left ? " (left)" : ""),
290	    winner: line.winner,
291	    left: line.left,
292	    cells: [line.collected, line.thefts, line.lost, line.duelsWon, line.duelsLost, line.duelsDrawn, line.gold, line.cachesClaimed, line.islandsVisited],
293	  }));
294	  return { headline, detail, rows };
295	}
296	
297	/** Everything the flow's part of the page shows, read from the synced state and this player's status. */
298	export interface FlowModel {
299	  readonly code: string;
300	  /** Another ship in sight is channelling the claim. */
301	  readonly rivalClaiming: boolean;
302	  readonly lobby: LobbyState;
303	  readonly remainingTicks: number;
304	  readonly finalSector: string;
305	  readonly claim: ClaimStatus | undefined;
306	  readonly own: { readonly x: number; readonly y: number; readonly speed: number } | undefined;
307	  readonly treasureRadius: number;
308	  readonly subUnitsPerTile: number;
309	  readonly results: ResultsState;
310	}
311	
312	/** Whether a position is inside the treasure circle around a route's point (the edge counts, as on the server). */
313	export function insideCircle(claim: ClaimStatus | undefined, own: { x: number; y: number } | undefined, radius: number): boolean {
314	  if (claim === undefined || !claim.routeKnown || own === undefined) return false;
315	  const dx = own.x - claim.routeX;
316	  const dy = own.y - claim.routeY;
317	  return dx * dx + dy * dy <= radius * radius;
318	}
319	
320	/** What the compass says while no route is known: shown, but inactive. */
321	export const NO_ROUTE_TEXT = "No treasure route yet: hold every rubbing type to learn it";
322	
323	/** The compass to the final island as the page shows it. */
324	export interface CompassView {
325	  /** Hidden outside play (the lobby, the ready check, the results); shown, inactive, while no route is known. */
326	  readonly hidden: boolean;
327	  /** The route's state: "none" (no route known), "inactive" (a type lost) or "active". */
328	  readonly state: string;
329	  /** Whether the arrow points anywhere: an active route only. */
330	  readonly active: boolean;
331	  /** Radians for the arrow (0 without an active route). */
332	  readonly bearing: number;
333	  /** Tiles to the treasure, with an active route and a known position only. */
334	  readonly distance: string | undefined;
335	  readonly text: string;
336	}
337	
338	/** Everything the flow's part of the page shows, element by element: `applyFlow` writes it without deciding anything. */
339	export interface FlowView {
340	  readonly phase: HudLine;
341	  readonly timer: HudLine;
342	  readonly remaining: string;
343	  readonly sector: string;
344	  readonly lobby: {
345	    readonly hidden: boolean;
346	    /** The lobby takes the purse's place until the match starts. */
347	    readonly purseHidden: boolean;
348	    readonly code: string;
349	    readonly players: readonly { readonly seat: number; readonly label: string }[];
350	    readonly startHidden: boolean;
351	    readonly startDisabled: boolean;
352	    /** With the ready check's seconds left in `seconds`. */
353	    readonly hint: HudLine;
354	  };
355	  readonly route: HudLine;
356	  readonly compass: CompassView;
357	  readonly claim: {
358	    readonly panelHidden: boolean;
359	    readonly text: HudLine;
360	    readonly risk: HudLine;
361	    readonly progressHidden: boolean;
362	    readonly progress: number;
363	    readonly held: string;
364	    readonly total: string;
365	  };
366	  readonly results: {
367	    readonly hidden: boolean;
368	    readonly reason: string;
369	    readonly winnerSeat: string;
370	    readonly headline: string;
371	    readonly detail: string;
372	    /** Each row's cells as shown: the player (with a trophy for the winner), then the accomplishments. */
373	    readonly rows: readonly { readonly seat: string; readonly winner: string; readonly cells: readonly string[] }[];
374	  };
375	}
376	
377	/** The flow's part of the page (§2, §5): the lobby, the clock bar, the compass, the claim panel and the results screen. */
378	export function flowView(model: FlowModel): FlowView {
379	  const { lobby } = model;
380	  const inLobby = lobby.phase === "lobby" || lobby.phase === "ready";
381	  const playing = lobby.phase === "departure" || lobby.phase === "exploration";
382	  const shown = lobbyModel(lobby);
383	  const route = routeLine(model.claim, model.own, model.subUnitsPerTile);
384	  const claim = claimLines(model.claim, {
385	    inCircle: insideCircle(model.claim, model.own, model.treasureRadius),
386	    speed: model.own?.speed ?? 0,
387	    worldTick: lobby.worldTick,
388	    phase: lobby.phase,
389	    rivalClaiming: model.rivalClaiming,
390	  });
391	  const results = resultsModel(model.results);
392	  return {
393	    phase: { text: phaseText(lobby.phase), state: lobby.phase },
394	    timer: timerLine({ phase: lobby.phase, remainingTicks: model.remainingTicks }),
395	    remaining: String(model.remainingTicks),
396	    sector: model.finalSector === "" ? "" : `Treasure sector: ${model.finalSector}`,
397	    lobby: {
398	      hidden: !inLobby,
399	      purseHidden: inLobby,
400	      code: model.code,
401	      players: shown.players,
402	      startHidden: !shown.showStart,
403	      startDisabled: !shown.canStart,
404	      hint: lobby.phase === "ready" ? { text: shown.hint, state: lobby.phase, seconds: secondsUntil(lobby.readyEndsAt, lobby.worldTick) } : { text: shown.hint, state: lobby.phase },
405	    },
406	    route,
407	    compass: {
408	      hidden: !playing,
409	      state: route.state,
410	      active: route.state === "active",
411	      bearing: route.bearing ?? 0,
412	      distance: route.distanceTiles === undefined ? undefined : String(route.distanceTiles),
413	      text: route.state === "none" ? NO_ROUTE_TEXT : route.text,
414	    },
415	    claim: {
416	      panelHidden: claim.claim.state === "none",
417	      text: claim.claim,
418	      risk: claim.risk,
419	      progressHidden: claim.claim.state !== "channel",
420	      progress: claim.progress,
421	      held: String(model.claim?.claimHeld ?? 0),
422	      total: String(model.claim?.claimTotal ?? 0),
423	    },
424	    results: {
425	      hidden: results === undefined,
426	      reason: model.results.endReason,
427	      winnerSeat: String(model.results.winnerSeat),
428	      headline: results?.headline ?? "",
429	      detail: results?.detail ?? "",
430	      rows: (results?.rows ?? []).map((row) => ({
431	        seat: String(row.seat),
432	        winner: String(row.winner),
433	        cells: [row.winner ? `${row.label} 🏆` : row.label, ...row.cells.map(String)],
434	      })),
435	    },
436	  };
437	}
