1	import { afterAll, beforeAll, describe, expect, it } from "vitest";
2	import { seaMap } from "@pirate-sea-race/content";
3	import { claimRules } from "@pirate-sea-race/content/claim";
4	import { intelRules } from "@pirate-sea-race/content/intel";
5	import { startGameServer, type RunningGameServer } from "@pirate-sea-race/server";
6	import { createIntelConfig, sectorName, sectorOf } from "@pirate-sea-race/simulation/intel";
7	import { sleep, type HeadlessClient } from "@pirate-sea-race/test-tools";
8	import { GUEST_SEAT, HOST_SEAT, placePair } from "./rubbingsSetup.js";
9	import { collectFullSet, controlStartOf, FINAL, flowTuning } from "./matchFlowSetup.js";
10	import { collectAt, containsText, dockFor, grapple, playersAt, roomOf, tracker } from "./seaDuelSetup.js";
11	
12	/**
13	 * §2 and §5's reveals through the real room, on raw frames: the first full set sends the final island's sector to
14	 * everyone and its exact claim point only to the holder; losing a type makes the holder's route inactive; the minute-20
15	 * and minute-28 broadcasts arrive for everyone. Test-only timings: the sector reveal 10 s after control start and the
16	 * carrier reveal 14 s after it (every 2 s from then), instead of minutes 20 and 28.
17	 */
18	const SECTOR_REVEAL_TICKS = 200;
19	const CARRIER_INTERVAL_TICKS = 40;
20	const CARRIER_REVEAL_TICKS = 280;
21	let server: RunningGameServer;
22	let endpoint: string;
23	
