94	    // The loser respawns moored at a dock: that island counts as visited too.
95	    await guest.waitFor(() => guest.status()?.mode === "sea" && guest.ship()!.dock >= 0, 10_000);
96	    const guestIslands = new Set([dockFor("moon").island, seaMap.docks[guest.ship()!.dock]!.island]).size;
97	    const results = await resultsOf(host, guest);
98	    expect(results).toMatchObject({ reason: "deadline", winnerSeat: 0, tick: controlStartOf(host) + MATCH_TICKS, elapsedTicks: MATCH_TICKS });
99	    for (const client of [host, guest]) expect(client.reveals.filter((reveal) => reveal.kind === "sector-reveal")).toEqual([]);
100	    expect(results.players).toEqual([
101	      line(host.seat, { rubbingsHeld: 2, collected: 1, thefts: 1, duelsWon: 1, gold: 60, islandsVisited: 1 }),
102	      line(guest.seat, { rubbingsHeld: 0, collected: 1, lost: 1, duelsLost: 1, gold: 40, islandsVisited: guestIslands }),
103	    ]);
104	  }, 35_000);
105	
106	  it("lets a claim completing on the deadline tick win", async ({ onTestFinished }) => {
107	    const track = tracker(onTestFinished);
108	    const [host, guest] = (await playersAt(endpoint, [HOST_SEAT, GUEST_SEAT], track)) as [HeadlessClient, HeadlessClient];
109	    await collectFullSet(host, endpoint);
110	    await host.placeShip(endpoint, CLAIM_SEAT);
111	    const room = roomOf(host);
112	    const deadline = controlStartOf(host) + MATCH_TICKS;
113	    expect(room.claimConfiguration!.deadlineTick).toBe(deadline);
114	    // The clock stops after the tick before the channel's start that completes it on the deadline tick; E goes
115	    // down while it is stopped, so the channel starts on the next tick.
116	    room.pauseAfterTick(deadline - CHANNEL - 1);
117	    await until(() => room.worldPaused, 20_000, "the pause");
118	    const stopped = room.matchState.worldTick;
119	    expect(stopped).toBe(deadline - CHANNEL - 1);
120	    const holding = host.holdUntil(HOLD_E, () => host.results() !== undefined, 8000);
121	    await sleep(250);
122	    // Stopped: no world tick ran meanwhile.
123	    expect(room.matchState.worldTick).toBe(stopped);
124	    room.resumeWorld();
125	    await holding;
126	    const results = await resultsOf(host, guest);
127	    expect(room.claimState!.result).toEqual({ reason: "claim", winner: host.sessionId, tick: deadline });
128	    expect(results).toMatchObject({ reason: "claim", winnerSeat: host.seat, tick: deadline, elapsedTicks: MATCH_TICKS });
129	    expect(results.players[0]).toEqual(line(host.seat, { winner: true, rubbingsHeld: 2, collected: 2, islandsVisited: 2 }));
130	  }, 35_000);
131	
132	  it("ends abandoned, with no winner, when everyone leaves after the start", async ({ onTestFinished }) => {
133	    const track = tracker(onTestFinished);
134	    const [host, guest] = (await playersAt(endpoint, [HOST_SEAT, GUEST_SEAT], track)) as [HeadlessClient, HeadlessClient];
135	    const code = host.code;
136	    const room = roomOf(host);
137	    await collectAt(host, endpoint, dockFor("sun"), "sun");
138	    const seats = [host.seat, guest.seat];
139	    await Promise.all([host.leave(), guest.leave()]);
140	    await until(() => recordedOutcomes().some((outcome) => outcome.code === code), 5000, "the recorded outcome");
141	    const results = recordedOutcomes().find((outcome) => outcome.code === code)!.results;
142	    expect(results).toMatchObject({ reason: "abandoned", winner: null, custom: true });
143	    // Neither holds a rubbing at the end, so the lines are in id order; compared here by seat.
144	    const bySeat = results.players.map(({ id, ...rest }) => ({ ...rest, seat: room.seatOf(id) })).sort((a, b) => a.seat - b.seat);
145	    expect(bySeat).toEqual([
146	      // The host's Sun went into a cache when it quit: collected, then lost.
147	      line(seats[0]!, { left: true, collected: 1, lost: 1, islandsVisited: 1 }),
148	      line(seats[1]!, { left: true }),
149	    ]);
150	    expectRoomChecks(room);
151	  });
152	
153	  it("counts a cancelled duel for neither fighter (neither readied its arena)", async ({ onTestFinished }) => {
154	    const track = tracker(onTestFinished);
155	    const [host, guest] = (await playersAt(endpoint, [HOST_SEAT, GUEST_SEAT], track, { clients: [{ autoReady: false }, { autoReady: false }] })) as [HeadlessClient, HeadlessClient];
