186	    const track = tracker(onTestFinished);
187	    const [host, guest] = (await playersAt(endpoint, [HOST_SEAT, GUEST_SEAT], track)) as [HeadlessClient, HeadlessClient];
188	    await collectAt(guest, endpoint, dockFor("moon"), "moon");
