203	    await host.waitFor(() => host.results() !== undefined, 5000);
204	    const results = host.results()!;
205	    expect(results).toMatchObject({ reason: "aborted", winnerSeat: 0 });
206	    expect(results.players).toEqual([
207	      line(seats[0]!, { rubbingsHeld: 1, thefts: 1, duelsWon: 1, gold: 60 }),
208	      line(seats[1]!, { left: true, collected: 1, lost: 1, duelsLost: 1, gold: 40, islandsVisited: 1 }),
209	    ]);
210	  }, 25_000);
211	
212	  it("ends aborted, with no winner and no penalty, on a server fault", async ({ onTestFinished }) => {
213	    const track = tracker(onTestFinished);
214	    const [host, guest] = (await playersAt(endpoint, [HOST_SEAT, GUEST_SEAT], track)) as [HeadlessClient, HeadlessClient];
215	    await collectAt(host, endpoint, dockFor("sun"), "sun");
216	    roomOf(host).injectFault();
217	    const results = await resultsOf(host, guest, 5000);
218	    expect(results).toMatchObject({ reason: "aborted", winnerSeat: 0 });
219	    expect(results.players).toEqual([line(host.seat, { rubbingsHeld: 1, collected: 1, islandsVisited: 1 }), line(guest.seat)]);
220	    // Nothing moves after the fault.
221	    const tick = roomOf(host).flowState.tick;
222	    await host.hold({ moveX: 0, moveY: -1 }, 300);
223	    expect(roomOf(host).flowState.tick).toBe(tick);
224	  });
225	});
