166	    // Back on the claim tile holding E, it cannot claim: no channel starts.
167	    await holder.waitFor(() => holder.status()?.mode === "sea", 8000);
168	    await holder.placeShip(endpoint, CLAIM_SEAT);
169	    await holder.hold(HOLD_E, 800);
