171	    expect(holder.claimView()!.claim).toBe("");
172	    expect(room.flowState.end).toBeNull();
173	  }, 45_000);
174	
175	  it("resets the channel when the holder's input stalls: a lapsed E is not held", async ({ onTestFinished }) => {
176	    const track = tracker(onTestFinished);
177	    const [host] = (await playersAt(endpoint, [CLAIM_SEAT, ASIDE], track)) as [HeadlessClient];
178	    await collectFullSet(host, endpoint);
179	    await host.placeShip(endpoint, CLAIM_SEAT);
