192	    const track = tracker(onTestFinished);
193	    // The holder never readies its arena: it forfeits the duel. The rival holds every type too, so it takes nothing.
194	    const [holder, rival] = (await playersAt(endpoint, [CLAIM_SEAT, CHALLENGER_SEAT], track, { clients: [{ autoReady: false }, {}] })) as [HeadlessClient, HeadlessClient];
195	    await collectFullSet(holder, endpoint);
196	    await collectFullSet(rival, endpoint);
197	    await holder.placeShip(endpoint, CLAIM_SEAT);
198	    await rival.placeShip(endpoint, CHALLENGER_SEAT);
199	    await grapple(rival, holder);
200	    await holder.waitFor(() => holder.status()?.mode === "respawning", 10_000);
201	    expect(holder.rubbings()).toEqual(["sun", "moon"]);
202	    const room = roomOf(holder);
203	    const ship = room.matchState.ships.find((each) => each.id === holder.sessionId)!;
204	    expect(Math.hypot(ship.x - FINAL.claimPoint.x, ship.y - FINAL.claimPoint.y)).toBeLessThanOrEqual(room.claimConfiguration!.circleRadius);
205	    expect(ship.speed).toBe(0);
206	    // E held through the whole wait: no channel starts.
207	    let channelled = false;
208	    const watch = setInterval(() => (channelled ||= channelOf(holder) !== null), 5);
209	    try {
210	      await holder.holdUntil(HOLD_E, () => holder.status()?.mode === "sea", 8000);
211	    } finally {
212	      clearInterval(watch);
213	    }
214	    expect(channelled).toBe(false);
215	    expect(room.claimState!.result).toBeNull();
216	  }, 45_000);
217	
218	  it("resets the channel when the holder's connection drops", async ({ onTestFinished }) => {
219	    const track = tracker(onTestFinished);
220	    const proxy = await ImpairmentProxy.start(server.port);
221	    onTestFinished(async () => void (await proxy.close()));
222	    const [host] = (await playersAt(endpoint, [CLAIM_SEAT, ASIDE], track, { endpoints: [proxy.endpoint, endpoint] })) as [HeadlessClient];
223	    // The SDK reconnects only a room it joined at least five seconds ago.
224	    const reconnectable = Date.now() + 5500;
225	    await collectFullSet(host, endpoint);
226	    await host.placeShip(endpoint, CLAIM_SEAT);
227	    await sleep(Math.max(0, reconnectable - Date.now() - 1000));
228	    const room = roomOf(host);
229	    const holding = host.hold(HOLD_E, 3000);
230	    await until(() => (channelOf(host)?.progress ?? 0) >= 20, 5000, "the channel under way");
231	    proxy.sever({ refuse: true });
232	    await holding;
233	    await until(() => channelOf(host) === null, 3000, "the reset");
234	    const status = room.state.status.get(host.sessionId)!;
235	    expect(status.claimInterrupt).toBe("disconnected");
236	    expect(room.claimState!.result).toBeNull();
237	    // Back within the seat's reservation, the player reads why the channel reset.
238	    await sleep(500);
239	    proxy.restore();
240	    await host.waitFor(() => host.connected && host.claimView()?.claimInterrupt === "disconnected", 12_000);
241	    expect(host.claimView()).toMatchObject({ claim: "", claimHeld: 0, routeX: FINAL.claimPoint.x });
242	  }, 45_000);
243	});
